<script setup lang="ts">
import { computed } from 'vue';
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { Plus, Save, Trash2 } from '@lucide/vue';
import AppLayout from '@/Layouts/AppLayout.vue';
const props = defineProps<{ employee:any; profile:any; history:any[] }>();
const page = usePage<any>();
const form = useForm({base_salary:props.profile?.base_salary === undefined ? null : Number(props.profile.base_salary), allowance:Number(props.profile?.allowance ?? 0), bpjs_health:Number(props.profile?.bpjs_health ?? 0), bpjs_employment:Number(props.profile?.bpjs_employment ?? 0), other_allowances:(props.profile?.other_allowances ?? []).map((a:any)=>({name:a.name,amount:Number(a.amount)})), reason:''});
const money = (v:any) => v === null || v === undefined ? 'Belum diatur' : new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v));
const fields:Record<string,string> = {base_salary:'Gaji Pokok',allowance:'Tunjangan Tetap',other_allowances:'Tunjangan Lainnya',bpjs_health:'BPJS Kesehatan',bpjs_employment:'BPJS Ketenagakerjaan'};
const format = (v:any) => Array.isArray(v) ? (v.length ? v.map(a => `${a.name}: ${money(a.amount)}`).join(', ') : 'Tidak ada') : money(v);
const salaryHistory = computed(() => props.history.flatMap(h => h.changes.filter((c:any)=>c.field === 'base_salary').map((c:any)=>({ ...c, created_at:h.created_at, actor_name:h.actor_name, reason:h.reason }))));
const submit = () => form.put(`/dashboard/payroll/salaries/${props.employee.id}`, {onSuccess:()=>form.reset('reason')});
</script>
<template><Head :title="`Data Gaji ${employee.fullName}`" /><AppLayout><main class="salary mx-auto max-w-[1500px] space-y-5 p-3 sm:p-5"><div class="flex flex-wrap items-center justify-between gap-4"><div><Link href="/dashboard/payroll/salaries" class="back">← Data Gaji Karyawan</Link><h1 class="mt-2 text-2xl font-black">{{ employee.fullName }}</h1><p class="muted mt-1 text-sm">Data gaji · {{ employee.role }} · {{ employee.isActive ? 'Aktif' : 'Tidak aktif' }}</p></div><button class="primary" :disabled="form.processing" @click="submit"><Save class="h-4 w-4" /> Simpan Data Gaji</button></div>
<div v-if="page.props.flash?.success" class="notice">{{ page.props.flash.success }}</div><div v-if="Object.keys(form.errors).length" class="error">{{ Object.values(form.errors).join(' ') }}</div>
<div class="grid gap-5 xl:grid-cols-2"><section class="panel"><h2>Komponen Gaji</h2><p class="muted mt-2 text-sm">Nilai bulanan dalam rupiah. Perubahan digunakan untuk payroll yang dibuat setelah data disimpan.</p><div class="mt-4 grid gap-4 sm:grid-cols-2"><label>Gaji Pokok (Rp)<input v-model.number="form.base_salary" type="number" min="0" placeholder="Belum diatur" required /></label><label>Tunjangan Tetap (Rp)<input v-model.number="form.allowance" type="number" min="0" required /></label></div><div class="mt-6 flex items-center justify-between gap-3"><h3 class="font-bold">Tunjangan Lainnya</h3><button class="secondary" @click="form.other_allowances.push({name:'',amount:0})"><Plus class="h-4 w-4" /> Tambah Tunjangan</button></div><p v-if="!form.other_allowances.length" class="muted mt-3 text-sm">Belum ada tunjangan tambahan.</p><div v-for="(allowance,index) in form.other_allowances" :key="index" class="mt-3 grid grid-cols-[1fr_1fr_auto] items-end gap-2"><label>Nama<input v-model="allowance.name" placeholder="Nama tunjangan" maxlength="100" /></label><label>Nominal (Rp)<input v-model.number="allowance.amount" type="number" min="0" /></label><button class="remove" :aria-label="`Hapus tunjangan ${index+1}`" @click="form.other_allowances.splice(index,1)"><Trash2 class="h-4 w-4" /></button></div></section>
<section class="panel"><h2>Potongan BPJS</h2><p class="muted mt-2 text-sm">Masukkan nominal potongan bulanan bagian pegawai sesuai perhitungan dan ketentuan kantor. Sistem tidak menghitung tarif BPJS otomatis.</p><div class="mt-4 grid gap-4"><label>BPJS Kesehatan (Rp)<input v-model.number="form.bpjs_health" type="number" min="0" /></label><label>BPJS Ketenagakerjaan (Rp)<input v-model.number="form.bpjs_employment" type="number" min="0" /></label><label>Alasan perubahan <span class="text-red-700">*</span><textarea v-model="form.reason" rows="3" maxlength="1000" placeholder="Contoh: penyesuaian gaji tahunan" required /></label></div><p class="muted mt-3 text-sm">Alasan wajib diisi dan dicatat bersama nilai sebelum dan sesudah.</p></section></div>
<section class="panel"><h2>Riwayat Kenaikan atau Penurunan Gaji</h2><div v-if="!salaryHistory.length" class="muted mt-3 text-sm">Belum ada riwayat gaji pokok.</div><div v-for="(entry,index) in salaryHistory" :key="index" class="entry"><div class="flex flex-wrap items-center justify-between gap-2"><strong>{{ entry.before === null ? 'Gaji awal' : Number(entry.after) > Number(entry.before) ? 'Kenaikan gaji' : 'Penurunan gaji' }}</strong><span class="muted text-sm">{{ entry.created_at }} · {{ entry.actor_name }}</span></div><p class="mt-2">{{ money(entry.before) }} → <strong>{{ money(entry.after) }}</strong></p><p class="muted mt-1 text-sm">Alasan: {{ entry.reason }}</p></div></section>
<section class="panel"><h2>Riwayat Perubahan Data Gaji</h2><div v-if="!history.length" class="muted mt-3 text-sm">Belum ada riwayat perubahan.</div><div v-for="entry in history" :key="entry.id" class="entry"><div class="flex flex-wrap items-center justify-between gap-2"><strong>{{ entry.actor_name }}</strong><span class="muted text-sm">{{ entry.created_at }}</span></div><p class="muted mt-2 text-sm">Alasan: {{ entry.reason }}</p><div class="changes-grid"><div v-for="change in entry.changes" :key="change.field" class="change"><strong>{{ fields[change.field] || change.field }}</strong><p class="muted mt-1 text-sm">Sebelum: {{ format(change.before) }}</p><p class="mt-1 text-sm">Sesudah: {{ format(change.after) }}</p></div></div></div></section>
</main></AppLayout></template>
<style scoped>
.salary{color:#261a11}.panel{background:#fff;border:1px solid #e8dfcf;border-radius:16px;padding:22px}.panel h2{font-size:1.05rem;font-weight:800}.muted{color:#70685e}.back{font-size:.85rem;font-weight:700;color:#815c00}.salary label{font-size:.85rem;font-weight:600}.salary input,.salary textarea{display:block;width:100%;margin-top:6px;border:1px solid #d8cdbd;border-radius:10px;background:#fff;color:#261a11;padding:10px}.primary,.secondary,.remove{display:inline-flex;align-items:center;justify-content:center;gap:7px;border-radius:10px;padding:10px 14px;font-weight:700;font-size:.85rem}.primary{background:#d4af37;color:#1b1505}.secondary{border:1px solid #c49b24;color:#785600;background:#fff}.remove{border:1px solid #efc5c5;color:#b42318}.notice,.error{padding:12px;border-radius:10px;background:#faf3e3}.error{background:#ffeded;color:#9b1c1c}.entry{margin-top:14px;padding:16px;background:#fbf8f1;border:1px solid #eee4d2;border-radius:12px}.changes-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:24px}.change{min-width:0;overflow-wrap:anywhere;border-top:1px solid #eee4d2;margin-top:12px;padding-top:12px}@media(max-width:640px){.changes-grid{grid-template-columns:1fr}}
</style>
